-- LINKA core persistence schema.
-- Private schema: expose these tables only through the authenticated backend.
-- UUIDs are generated by the application; no database extension is required.
BEGIN;

CREATE SCHEMA IF NOT EXISTS linka_private;
SET LOCAL search_path = linka_private, public;

CREATE TABLE IF NOT EXISTS schema_migrations (
    version TEXT PRIMARY KEY,
    description TEXT NOT NULL,
    applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS accounts (
    account_id UUID PRIMARY KEY,
    email_normalized TEXT NOT NULL UNIQUE,
    display_name TEXT NOT NULL,
    password_hash TEXT,
    account_status TEXT NOT NULL DEFAULT 'active'
        CHECK (account_status IN ('active', 'suspended', 'deletion_pending', 'deleted')),
    email_verified_at TIMESTAMPTZ,
    phone_e164 TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (email_normalized = lower(btrim(email_normalized))),
    CHECK (length(email_normalized) BETWEEN 3 AND 320),
    CHECK (length(btrim(display_name)) BETWEEN 1 AND 100),
    CHECK (phone_e164 IS NULL OR phone_e164 ~ '^\+[1-9][0-9]{1,14}$')
);

CREATE TABLE IF NOT EXISTS user_devices (
    device_id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES accounts(account_id) ON DELETE RESTRICT,
    device_fingerprint CHAR(64) NOT NULL UNIQUE
        CHECK (device_fingerprint ~ '^[0-9A-F]{64}$'),
    signing_public_key_der BYTEA NOT NULL
        CHECK (octet_length(signing_public_key_der) BETWEEN 64 AND 512),
    platform TEXT NOT NULL CHECK (platform IN ('android', 'web', 'other')),
    device_name TEXT,
    relay_consent BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_seen_at TIMESTAMPTZ,
    revoked_at TIMESTAMPTZ,
    UNIQUE (device_id, account_id)
);

CREATE INDEX IF NOT EXISTS user_devices_account_active_idx
    ON user_devices (account_id, created_at DESC)
    WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS auth_sessions (
    session_id UUID PRIMARY KEY,
    account_id UUID NOT NULL,
    device_id UUID NOT NULL,
    token_hash BYTEA NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    issued_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    FOREIGN KEY (device_id, account_id)
        REFERENCES user_devices(device_id, account_id) ON DELETE RESTRICT,
    CHECK (expires_at > issued_at)
);

CREATE INDEX IF NOT EXISTS auth_sessions_active_device_idx
    ON auth_sessions (device_id, expires_at)
    WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS telephony_providers (
    provider_id TEXT PRIMARY KEY,
    display_name TEXT NOT NULL,
    provider_kind TEXT NOT NULL
        CHECK (provider_kind IN ('numbering', 'voice', 'messaging', 'payment', 'other')),
    provider_status TEXT NOT NULL DEFAULT 'configured'
        CHECK (provider_status IN ('configured', 'enabled', 'disabled', 'retired')),
    public_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (length(btrim(provider_id)) BETWEEN 1 AND 100),
    CHECK (length(btrim(display_name)) BETWEEN 1 AND 160)
);

CREATE TABLE IF NOT EXISTS telephone_numbers (
    number_id UUID PRIMARY KEY,
    provider_id TEXT NOT NULL REFERENCES telephony_providers(provider_id) ON DELETE RESTRICT,
    provider_number_ref TEXT NOT NULL,
    e164 TEXT NOT NULL CHECK (e164 ~ '^\+[1-9][0-9]{1,14}$'),
    country_iso2 CHAR(2) NOT NULL CHECK (country_iso2 ~ '^[A-Z]{2}$'),
    number_type TEXT NOT NULL
        CHECK (number_type IN ('mobile', 'landline', 'toll_free', 'premium', 'other', 'unknown')),
    lifecycle_status TEXT NOT NULL
        CHECK (lifecycle_status IN ('inventory', 'reserved', 'active', 'porting', 'releasing', 'released', 'suspended')),
    assigned_account_id UUID REFERENCES accounts(account_id) ON DELETE RESTRICT,
    supports_voice BOOLEAN NOT NULL DEFAULT FALSE,
    supports_sms BOOLEAN NOT NULL DEFAULT FALSE,
    supports_mms BOOLEAN NOT NULL DEFAULT FALSE,
    provider_capabilities JSONB NOT NULL DEFAULT '{}'::jsonb,
    rental_currency CHAR(3),
    rental_amount_minor BIGINT,
    billing_period TEXT CHECK (billing_period IN ('month', 'year')),
    next_renewal_at TIMESTAMPTZ,
    acquired_at TIMESTAMPTZ,
    released_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider_id, provider_number_ref),
    CHECK (
        (lifecycle_status IN ('reserved', 'active', 'porting', 'releasing', 'suspended')
            AND assigned_account_id IS NOT NULL)
        OR
        (lifecycle_status IN ('inventory', 'released') AND assigned_account_id IS NULL)
    ),
    CHECK ((rental_currency IS NULL) = (rental_amount_minor IS NULL)),
    CHECK (rental_amount_minor IS NULL OR rental_amount_minor >= 0),
    CHECK ((billing_period IS NULL) OR rental_amount_minor IS NOT NULL)
);

CREATE UNIQUE INDEX IF NOT EXISTS telephone_numbers_one_active_owner_idx
    ON telephone_numbers (e164)
    WHERE lifecycle_status IN ('reserved', 'active', 'porting', 'releasing', 'suspended');

CREATE INDEX IF NOT EXISTS telephone_numbers_inventory_idx
    ON telephone_numbers (country_iso2, number_type, e164)
    WHERE lifecycle_status = 'inventory';

CREATE INDEX IF NOT EXISTS telephone_numbers_account_idx
    ON telephone_numbers (assigned_account_id, lifecycle_status)
    WHERE assigned_account_id IS NOT NULL;

CREATE TABLE IF NOT EXISTS provider_rates (
    rate_id TEXT PRIMARY KEY,
    provider_id TEXT NOT NULL REFERENCES telephony_providers(provider_id) ON DELETE RESTRICT,
    route_id TEXT NOT NULL,
    provider_tariff_ref TEXT NOT NULL,
    rate_version TEXT NOT NULL,
    service TEXT NOT NULL CHECK (service IN ('voice', 'sms', 'mms')),
    destination_country_iso2 CHAR(2) NOT NULL CHECK (destination_country_iso2 ~ '^[A-Z]{2}$'),
    destination_prefix TEXT NOT NULL CHECK (destination_prefix ~ '^\+[1-9][0-9]{0,14}$'),
    number_type TEXT NOT NULL
        CHECK (number_type IN ('mobile', 'landline', 'other', 'unknown', 'any')),
    billing_unit TEXT NOT NULL CHECK (billing_unit IN ('minute', 'message')),
    billing_increment_units BIGINT NOT NULL CHECK (billing_increment_units > 0),
    minimum_billable_units BIGINT NOT NULL CHECK (minimum_billable_units > 0),
    credit_units_per_increment BIGINT NOT NULL
        CHECK (credit_units_per_increment BETWEEN 1 AND 9007199254740991),
    effective_from TIMESTAMPTZ NOT NULL,
    effective_until TIMESTAMPTZ,
    imported_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    source_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    CHECK (
        (service = 'voice' AND billing_unit = 'minute')
        OR
        (service IN ('sms', 'mms') AND billing_unit = 'message')
    ),
    CHECK (effective_until IS NULL OR effective_until > effective_from)
);

CREATE INDEX IF NOT EXISTS provider_rates_lookup_idx
    ON provider_rates (
        provider_id, service, destination_country_iso2, destination_prefix,
        number_type, effective_from DESC
    );

CREATE TABLE IF NOT EXISTS wallet_accounts (
    wallet_id UUID PRIMARY KEY,
    account_id UUID NOT NULL UNIQUE REFERENCES accounts(account_id) ON DELETE RESTRICT,
    purchased_credit_units BIGINT NOT NULL DEFAULT 0 CHECK (purchased_credit_units >= 0),
    promotional_credit_units BIGINT NOT NULL DEFAULT 0 CHECK (promotional_credit_units >= 0),
    sponsored_credit_units BIGINT NOT NULL DEFAULT 0 CHECK (sponsored_credit_units >= 0),
    version BIGINT NOT NULL DEFAULT 0 CHECK (version >= 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (
        purchased_credit_units::NUMERIC +
        promotional_credit_units::NUMERIC +
        sponsored_credit_units::NUMERIC <= 9007199254740991
    )
);

CREATE TABLE IF NOT EXISTS wallet_ledger_events (
    event_id TEXT PRIMARY KEY,
    wallet_id UUID NOT NULL REFERENCES wallet_accounts(wallet_id) ON DELETE RESTRICT,
    account_id UUID NOT NULL REFERENCES accounts(account_id) ON DELETE RESTRICT,
    idempotency_key TEXT NOT NULL,
    event_type TEXT NOT NULL CHECK (event_type IN (
        'PURCHASE_CONFIRMED', 'PROMOTIONAL_GRANT', 'REFERRAL_GRANT',
        'SPONSORED_GRANT', 'CALL_USAGE', 'MESSAGE_USAGE',
        'NUMBER_RENTAL', 'NUMBER_RENEWAL', 'REFUND'
    )),
    credit_source TEXT NOT NULL CHECK (credit_source IN ('purchased', 'promotional', 'sponsored')),
    amount_credit_units BIGINT NOT NULL
        CHECK (amount_credit_units BETWEEN 1 AND 9007199254740991),
    reference_id TEXT,
    reverses_event_id TEXT REFERENCES wallet_ledger_events(event_id) ON DELETE RESTRICT,
    provider_reference TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
    UNIQUE (account_id, idempotency_key),
    CHECK (length(btrim(event_id)) BETWEEN 1 AND 128),
    CHECK (length(btrim(idempotency_key)) BETWEEN 1 AND 200),
    CHECK ((event_type = 'REFUND') = (reverses_event_id IS NOT NULL)),
    CHECK (
        (event_type = 'PURCHASE_CONFIRMED' AND credit_source = 'purchased')
        OR (event_type IN ('PROMOTIONAL_GRANT', 'REFERRAL_GRANT') AND credit_source = 'promotional')
        OR (event_type = 'SPONSORED_GRANT' AND credit_source = 'sponsored')
        OR event_type IN ('CALL_USAGE', 'MESSAGE_USAGE', 'NUMBER_RENTAL', 'NUMBER_RENEWAL', 'REFUND')
    )
);

CREATE INDEX IF NOT EXISTS wallet_ledger_account_history_idx
    ON wallet_ledger_events (account_id, created_at DESC);

CREATE INDEX IF NOT EXISTS wallet_ledger_reference_idx
    ON wallet_ledger_events (reference_id)
    WHERE reference_id IS NOT NULL;

CREATE OR REPLACE FUNCTION reject_wallet_ledger_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = linka_private, pg_temp
AS $function$
BEGIN
    RAISE EXCEPTION 'wallet_ledger_is_append_only' USING ERRCODE = 'P0001';
END;
$function$;

DROP TRIGGER IF EXISTS wallet_ledger_append_only ON wallet_ledger_events;
CREATE TRIGGER wallet_ledger_append_only
    BEFORE UPDATE OR DELETE ON wallet_ledger_events
    FOR EACH ROW EXECUTE FUNCTION reject_wallet_ledger_mutation();

CREATE OR REPLACE FUNCTION apply_wallet_event(
    p_event_id TEXT,
    p_idempotency_key TEXT,
    p_account_id UUID,
    p_event_type TEXT,
    p_credit_source TEXT,
    p_amount_credit_units BIGINT,
    p_reference_id TEXT DEFAULT NULL,
    p_reverses_event_id TEXT DEFAULT NULL
)
RETURNS TABLE (
    event_status TEXT,
    purchased_credit_units BIGINT,
    promotional_credit_units BIGINT,
    sponsored_credit_units BIGINT
)
LANGUAGE plpgsql
SET search_path = linka_private, pg_temp
AS $function$
DECLARE
    v_wallet wallet_accounts%ROWTYPE;
    v_prior wallet_ledger_events%ROWTYPE;
    v_original wallet_ledger_events%ROWTYPE;
    v_required_source TEXT;
    v_current_balance BIGINT;
    v_next_balance BIGINT;
    v_purchased BIGINT;
    v_promotional BIGINT;
    v_sponsored BIGINT;
    v_already_refunded NUMERIC;
BEGIN
    IF p_event_id IS NULL OR length(btrim(p_event_id)) NOT BETWEEN 1 AND 128
       OR p_idempotency_key IS NULL OR length(btrim(p_idempotency_key)) NOT BETWEEN 1 AND 200
       OR p_account_id IS NULL
       OR p_amount_credit_units IS NULL
       OR p_amount_credit_units NOT BETWEEN 1 AND 9007199254740991 THEN
        RAISE EXCEPTION 'invalid_ledger_event' USING ERRCODE = '22023';
    END IF;

    SELECT * INTO v_wallet
    FROM wallet_accounts
    WHERE account_id = p_account_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'wallet_not_found' USING ERRCODE = 'P0002';
    END IF;

    SELECT * INTO v_prior
    FROM wallet_ledger_events
    WHERE account_id = p_account_id AND idempotency_key = p_idempotency_key;

    IF FOUND THEN
        IF v_prior.event_id = p_event_id
           AND v_prior.event_type = p_event_type
           AND v_prior.credit_source = p_credit_source
           AND v_prior.amount_credit_units = p_amount_credit_units
           AND v_prior.reference_id IS NOT DISTINCT FROM p_reference_id
           AND v_prior.reverses_event_id IS NOT DISTINCT FROM p_reverses_event_id THEN
            RETURN QUERY SELECT
                'duplicate'::TEXT,
                v_wallet.purchased_credit_units,
                v_wallet.promotional_credit_units,
                v_wallet.sponsored_credit_units;
            RETURN;
        END IF;
        RAISE EXCEPTION 'idempotency_conflict' USING ERRCODE = '23505';
    END IF;

    IF EXISTS (SELECT 1 FROM wallet_ledger_events WHERE event_id = p_event_id) THEN
        RAISE EXCEPTION 'duplicate_event_id' USING ERRCODE = '23505';
    END IF;

    IF p_credit_source NOT IN ('purchased', 'promotional', 'sponsored') THEN
        RAISE EXCEPTION 'invalid_credit_source' USING ERRCODE = '22023';
    END IF;

    v_required_source := CASE p_event_type
        WHEN 'PURCHASE_CONFIRMED' THEN 'purchased'
        WHEN 'PROMOTIONAL_GRANT' THEN 'promotional'
        WHEN 'REFERRAL_GRANT' THEN 'promotional'
        WHEN 'SPONSORED_GRANT' THEN 'sponsored'
        ELSE NULL
    END;

    IF p_event_type IN (
        'PURCHASE_CONFIRMED', 'PROMOTIONAL_GRANT', 'REFERRAL_GRANT', 'SPONSORED_GRANT'
    ) THEN
        IF p_credit_source <> v_required_source OR p_reverses_event_id IS NOT NULL THEN
            RAISE EXCEPTION 'invalid_credit_source' USING ERRCODE = '22023';
        END IF;
    ELSIF p_event_type IN ('CALL_USAGE', 'MESSAGE_USAGE', 'NUMBER_RENTAL', 'NUMBER_RENEWAL') THEN
        IF p_reverses_event_id IS NOT NULL THEN
            RAISE EXCEPTION 'invalid_ledger_event' USING ERRCODE = '22023';
        END IF;
    ELSIF p_event_type = 'REFUND' THEN
        IF p_reverses_event_id IS NULL THEN
            RAISE EXCEPTION 'invalid_refund' USING ERRCODE = '22023';
        END IF;

        SELECT * INTO v_original
        FROM wallet_ledger_events
        WHERE event_id = p_reverses_event_id AND account_id = p_account_id
        FOR UPDATE;

        IF NOT FOUND
           OR v_original.event_type NOT IN ('CALL_USAGE', 'MESSAGE_USAGE', 'NUMBER_RENTAL', 'NUMBER_RENEWAL')
           OR v_original.credit_source <> p_credit_source THEN
            RAISE EXCEPTION 'invalid_refund' USING ERRCODE = '22023';
        END IF;

        SELECT COALESCE(SUM(amount_credit_units), 0)
        INTO v_already_refunded
        FROM wallet_ledger_events
        WHERE reverses_event_id = v_original.event_id AND event_type = 'REFUND';

        IF v_already_refunded + p_amount_credit_units > v_original.amount_credit_units THEN
            RAISE EXCEPTION 'refund_exceeds_usage' USING ERRCODE = '22023';
        END IF;
    ELSE
        RAISE EXCEPTION 'unsupported_ledger_event' USING ERRCODE = '22023';
    END IF;

    CASE p_credit_source
        WHEN 'purchased' THEN v_current_balance := v_wallet.purchased_credit_units;
        WHEN 'promotional' THEN v_current_balance := v_wallet.promotional_credit_units;
        ELSE v_current_balance := v_wallet.sponsored_credit_units;
    END CASE;

    IF p_event_type IN ('CALL_USAGE', 'MESSAGE_USAGE', 'NUMBER_RENTAL', 'NUMBER_RENEWAL') THEN
        IF v_current_balance < p_amount_credit_units THEN
            RAISE EXCEPTION 'insufficient_credits' USING ERRCODE = 'P0001';
        END IF;
        v_next_balance := v_current_balance - p_amount_credit_units;
    ELSE
        v_next_balance := v_current_balance + p_amount_credit_units;
    END IF;

    IF v_next_balance < 0 OR v_next_balance > 9007199254740991 THEN
        RAISE EXCEPTION 'wallet_balance_overflow' USING ERRCODE = '22003';
    END IF;

    v_purchased := v_wallet.purchased_credit_units;
    v_promotional := v_wallet.promotional_credit_units;
    v_sponsored := v_wallet.sponsored_credit_units;

    CASE p_credit_source
        WHEN 'purchased' THEN v_purchased := v_next_balance;
        WHEN 'promotional' THEN v_promotional := v_next_balance;
        ELSE v_sponsored := v_next_balance;
    END CASE;

    IF v_purchased::NUMERIC + v_promotional::NUMERIC + v_sponsored::NUMERIC > 9007199254740991 THEN
        RAISE EXCEPTION 'wallet_balance_overflow' USING ERRCODE = '22003';
    END IF;

    INSERT INTO wallet_ledger_events (
        event_id, wallet_id, account_id, idempotency_key,
        event_type, credit_source, amount_credit_units,
        reference_id, reverses_event_id
    ) VALUES (
        p_event_id, v_wallet.wallet_id, p_account_id, p_idempotency_key,
        p_event_type, p_credit_source, p_amount_credit_units,
        p_reference_id, p_reverses_event_id
    );

    UPDATE wallet_accounts
    SET purchased_credit_units = v_purchased,
        promotional_credit_units = v_promotional,
        sponsored_credit_units = v_sponsored,
        version = version + 1,
        updated_at = now()
    WHERE wallet_id = v_wallet.wallet_id;

    RETURN QUERY SELECT 'applied'::TEXT, v_purchased, v_promotional, v_sponsored;
END;
$function$;

CREATE TABLE IF NOT EXISTS payment_transactions (
    payment_id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES accounts(account_id) ON DELETE RESTRICT,
    provider_id TEXT NOT NULL REFERENCES telephony_providers(provider_id) ON DELETE RESTRICT,
    provider_payment_ref TEXT,
    idempotency_key TEXT NOT NULL,
    payment_status TEXT NOT NULL
        CHECK (payment_status IN ('pending', 'authorized', 'succeeded', 'failed', 'cancelled', 'refunded', 'partially_refunded')),
    currency CHAR(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
    amount_minor BIGINT NOT NULL CHECK (amount_minor > 0),
    credit_units_granted BIGINT NOT NULL CHECK (credit_units_granted BETWEEN 0 AND 9007199254740991),
    price_version TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (account_id, idempotency_key),
    UNIQUE (provider_id, provider_payment_ref)
);

CREATE TABLE IF NOT EXISTS provider_webhook_events (
    webhook_id UUID PRIMARY KEY,
    provider_id TEXT NOT NULL REFERENCES telephony_providers(provider_id) ON DELETE RESTRICT,
    provider_event_ref TEXT NOT NULL,
    event_type TEXT NOT NULL,
    payload_sha256 BYTEA NOT NULL CHECK (octet_length(payload_sha256) = 32),
    signature_verified_at TIMESTAMPTZ,
    processed_at TIMESTAMPTZ,
    processing_status TEXT NOT NULL DEFAULT 'received'
        CHECK (processing_status IN ('received', 'verified', 'processed', 'rejected', 'failed')),
    received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (provider_id, provider_event_ref)
);

CREATE TABLE IF NOT EXISTS call_sessions (
    call_id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES accounts(account_id) ON DELETE RESTRICT,
    device_id UUID,
    destination_account_id UUID REFERENCES accounts(account_id) ON DELETE RESTRICT,
    destination_number_id UUID REFERENCES telephone_numbers(number_id) ON DELETE RESTRICT,
    destination_e164 TEXT CHECK (destination_e164 IS NULL OR destination_e164 ~ '^\+[1-9][0-9]{1,14}$'),
    call_mode TEXT NOT NULL CHECK (call_mode IN ('internal', 'nearby', 'mesh', 'internet', 'carrier')),
    call_status TEXT NOT NULL CHECK (call_status IN ('initiated', 'ringing', 'answered', 'completed', 'rejected', 'failed', 'cancelled')),
    provider_id TEXT REFERENCES telephony_providers(provider_id) ON DELETE RESTRICT,
    rate_id TEXT REFERENCES provider_rates(rate_id) ON DELETE RESTRICT,
    rate_version TEXT,
    paid_quote_id TEXT,
    paid_consent_at TIMESTAMPTZ,
    started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    answered_at TIMESTAMPTZ,
    ended_at TIMESTAMPTZ,
    duration_seconds BIGINT,
    credits_charged BIGINT NOT NULL DEFAULT 0 CHECK (credits_charged BETWEEN 0 AND 9007199254740991),
    CHECK (answered_at IS NULL OR answered_at >= started_at),
    CHECK (ended_at IS NULL OR ended_at >= started_at),
    CHECK (duration_seconds IS NULL OR duration_seconds >= 0),
    CHECK (call_mode <> 'carrier' OR destination_e164 IS NOT NULL OR destination_number_id IS NOT NULL),
    CHECK (credits_charged = 0 OR paid_consent_at IS NOT NULL)
);

CREATE INDEX IF NOT EXISTS call_sessions_account_history_idx
    ON call_sessions (account_id, started_at DESC);

CREATE TABLE IF NOT EXISTS conversations (
    conversation_id UUID PRIMARY KEY,
    conversation_kind TEXT NOT NULL CHECK (conversation_kind IN ('direct', 'group')),
    created_by_account_id UUID NOT NULL REFERENCES accounts(account_id) ON DELETE RESTRICT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS conversation_members (
    conversation_id UUID NOT NULL REFERENCES conversations(conversation_id) ON DELETE RESTRICT,
    account_id UUID NOT NULL REFERENCES accounts(account_id) ON DELETE RESTRICT,
    joined_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    left_at TIMESTAMPTZ,
    PRIMARY KEY (conversation_id, account_id),
    CHECK (left_at IS NULL OR left_at >= joined_at)
);

CREATE TABLE IF NOT EXISTS internal_messages (
    message_id UUID PRIMARY KEY,
    conversation_id UUID NOT NULL REFERENCES conversations(conversation_id) ON DELETE RESTRICT,
    sender_account_id UUID NOT NULL REFERENCES accounts(account_id) ON DELETE RESTRICT,
    ciphertext BYTEA NOT NULL CHECK (octet_length(ciphertext) > 0),
    encryption_version TEXT NOT NULL,
    attachment_manifest JSONB NOT NULL DEFAULT '[]'::jsonb,
    sent_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    edited_at TIMESTAMPTZ,
    deleted_at TIMESTAMPTZ,
    CHECK (jsonb_typeof(attachment_manifest) = 'array')
);

CREATE INDEX IF NOT EXISTS internal_messages_conversation_idx
    ON internal_messages (conversation_id, sent_at DESC);

CREATE TABLE IF NOT EXISTS external_message_jobs (
    message_job_id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES accounts(account_id) ON DELETE RESTRICT,
    provider_id TEXT NOT NULL REFERENCES telephony_providers(provider_id) ON DELETE RESTRICT,
    sender_number_id UUID REFERENCES telephone_numbers(number_id) ON DELETE RESTRICT,
    destination_e164 TEXT NOT NULL CHECK (destination_e164 ~ '^\+[1-9][0-9]{1,14}$'),
    message_type TEXT NOT NULL CHECK (message_type IN ('sms', 'mms')),
    delivery_status TEXT NOT NULL
        CHECK (delivery_status IN ('queued', 'submitted', 'delivered', 'failed', 'undelivered', 'cancelled')),
    provider_message_ref TEXT,
    rate_id TEXT REFERENCES provider_rates(rate_id) ON DELETE RESTRICT,
    rate_version TEXT,
    credit_quote_id TEXT,
    paid_consent_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    delivered_at TIMESTAMPTZ,
    CHECK (rate_id IS NULL OR paid_consent_at IS NOT NULL),
    UNIQUE (provider_id, provider_message_ref)
);

CREATE INDEX IF NOT EXISTS external_message_jobs_account_history_idx
    ON external_message_jobs (account_id, created_at DESC);

INSERT INTO schema_migrations (version, description)
VALUES ('0001_core_schema', 'LINKA accounts, devices, providers, numbers, rates, wallet, payments, calls and messaging')
ON CONFLICT (version) DO NOTHING;

COMMIT;
